Rewrite the following GNU C++17 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++17 code you have to rewrite:
<original_code>
#include "bits/stdc++.h"
using namespace std;
#define MOD 1000000007
#define inf 0x3f3f3f3f3f3f3f3f
#define pi acos(-1.0)
#define ri register int
#define int long long
#define all(x) x.begin(), x.end()
#ifdef ONLINE_JUDGE
const int maxn = 3e5 + 10;
#else
const int maxn = 1e3 + 10;
#endif
//__builtin_popcount
char str[maxn];
int N;
signed main() {
#ifdef ONLINE_JUDGE
    ios::sync_with_stdio(false);
    cin.tie(0);
#endif
    // freopen("C:\Users\hjw\Downloads\testdata (4).in", "r", stdin);
    cin >> str + 1;
    N = strlen(str + 1);
    vector<vector<string>> dp(N + 1);
    dp[0].push_back("");

    for (int i = 1; i <= N; ++i) {
        if (i >= 2 && str[i - 1] == 'a' && str[i] == 't') {
            for (auto e : dp[i - 2]) {
                if (e.empty() || e.find('@') != e.npos) {
                    continue;
                }
                dp[i].push_back(e + "@");
            }

        } else if (i >= 3 && str[i - 2] == 'd' && str[i - 1] == 'o' &&
                   str[i] == 't') {
            for (auto e : dp[i - 3]) {
                if (e.empty()) {
                    continue;
                }
                dp[i].push_back(e + ".");
            }
        }
        for (auto e : dp[i - 1]) {
            dp[i].push_back(e + str[i]);
        }
    }
    vector<string> ans;
    for (auto e : dp[N]) {
        if (e.empty())
            continue;
        if (e.find('@') != e.npos && e.back() != '@' && e.back() != '.') {
            ans.push_back(e);
        }
    }
    sort(all(ans));
    cout << ans.front() << endl;

#ifndef ONLINE_JUDGE
    system("pause");
#endif
    return 0;
}
</original_code>
